using System.Text.Json;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Primitives;
using Avalonia.Input;
using Avalonia.Input.Raw;
using Avalonia.Media.Imaging;
using Avalonia.VisualTree;
namespace LtcPlayer.Avalonia;
public static class CueSelectionScrollVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);var results=new List<object>();var events=new List<object>();bool failed=false;
  var grid=w.FindControl<DataGrid>("CueGrid")!;var outer=w.FindControl<ScrollViewer>("WorkspaceScroll")!;var tools=w.FindControl<StackPanel>("EditorTools")!;
  void Check(bool ok,string message){if(!ok)throw new IOException(message);}
  async Task Stable(){string? previous=null;int same=0;for(int i=0;i<150;i++){await Task.Delay(20);string now=$"{w.ClientSize}|{outer.Offset}|{outer.Extent}|{grid.Bounds}|{tools.TranslatePoint(default,w)}";same=now==previous?same+1:0;previous=now;if(same>=5)return;}throw new TimeoutException("Layout did not stabilize");}
  object Snapshot()=>new{Outer=outer.Offset,ListBars=grid.GetVisualDescendants().OfType<ScrollBar>().Where(s=>s.TemplatedParent==grid).Select(s=>new{s.Name,s.Value,s.Maximum}).ToArray(),Inner=grid.GetVisualDescendants().OfType<ScrollViewer>().Select(s=>new{s.Name,s.Offset}).ToArray(),Selected=grid.SelectedItems.OfType<LtcPlayer.App.CueRow>().Select(r=>r.CueId).ToArray(),Focus=w.FocusManager?.GetFocusedElement()?.GetType().Name,Tools=tools.TranslatePoint(default,w),Header=grid.GetVisualDescendants().OfType<DataGridColumnHeadersPresenter>().FirstOrDefault()?.TranslatePoint(default,w)};
  void Capture(string name){using var bitmap=new RenderTargetBitmap(new PixelSize((int)w.ClientSize.Width,(int)w.ClientSize.Height),new Vector(96,96));bitmap.Render(w);bitmap.Save(Path.Combine(folder,name+".png"));}
  void Click(Control target,KeyModifiers modifiers=KeyModifiers.None){var pointer=new Pointer(19,PointerType.Mouse,true);var point=new Point(target.Bounds.Width/2,target.Bounds.Height/2);target.RaiseEvent(new PointerPressedEventArgs(target,pointer,target,point,0,new PointerPointProperties(RawInputModifiers.LeftMouseButton,PointerUpdateKind.LeftButtonPressed),modifiers,1));target.RaiseEvent(new PointerReleasedEventArgs(target,pointer,target,point,1,new PointerPointProperties(RawInputModifiers.None,PointerUpdateKind.LeftButtonReleased),modifiers,MouseButton.Left));}
  Control Cell(int index)=>grid.GetVisualDescendants().OfType<TextBlock>().First(t=>t.DataContext==w.Editor.Rows[index]&&t.Text==w.Editor.Rows[index].Name).GetVisualAncestors().OfType<DataGridCell>().First();
  async Task Test(string name,Func<Task> action){try{await action();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  async Task Unmoved(string name,Action action){await Stable();var offset=outer.Offset;double y=tools.TranslatePoint(default,w)!.Value.Y;var before=Snapshot();Capture(name+"-before");action();await Stable();var after=Snapshot();Capture(name+"-after");events.Add(new{name,before,after});Check(Math.Abs(outer.Offset.Y-offset.Y)<1&&Math.Abs(tools.TranslatePoint(default,w)!.Value.Y-y)<1,"Visible cue moved outer workspace");}
  try{
   await DefaultTestShow.LoadAsync(w.Editor);
   outer.AddHandler(Control.RequestBringIntoViewEvent,(_,e)=>events.Add(new{RequestSource=e.Source?.GetType().Name,Target=e.TargetObject?.GetType().Name,e.TargetRect,Offset=outer.Offset,Focus=w.FocusManager?.GetFocusedElement()?.GetType().Name}),global::Avalonia.Interactivity.RoutingStrategies.Bubble,true);
   foreach(int height in new[]{650,500,940})foreach(int count in new[]{4,1}){
    await Test($"visible file click and repeat {height} {count}",async()=>{while(w.Editor.Rows.Count>count)w.Editor.Rows.RemoveAt(w.Editor.Rows.Count-1);while(w.Editor.Rows.Count<count)w.Editor.Rows.Add(w.Editor.Rows[0].CloneDisabled());w.Width=1640;w.Height=height;w.FocusManager?.ClearFocus();await Stable();outer.Offset=default;await Stable();int index=count-1;await Unmoved($"file-{height}-{count}",()=>Click(Cell(index)));Check(grid.SelectedItem==w.Editor.Rows[index],"Click did not select cue");await Unmoved($"repeat-{height}-{count}",()=>Click(Cell(index)));});
   }
   w.Width=1640;w.Height=650;await Stable();
   await Test("visible click preserves manually scrolled position",async()=>{outer.Offset=new Vector(0,24);await Stable();await Unmoved("manual-offset",()=>Click(Cell(0)));});
   await Test("timecode focus and edit preserve workspace",async()=>{outer.Offset=default;await Stable();var box=grid.GetVisualDescendants().OfType<TextBox>().First(b=>b.Classes.Contains("timecode"));await Unmoved("timecode",()=>{Click(box);box.Focus(NavigationMethod.Pointer);});Check(box.IsFocused,"TC not focused");var text=box.Text;box.Text="01";box.RaiseEvent(new KeyEventArgs{RoutedEvent=InputElement.KeyDownEvent,Key=Key.Escape});Check(box.Text==text,"Escape did not cancel edit");});
   await Test("checkbox remains operable",async()=>{outer.Offset=default;await Stable();var check=grid.GetVisualDescendants().OfType<CheckBox>().First(b=>b.Classes.Contains("cue-enabled"));bool old=w.Editor.Rows[0].Enabled;await Unmoved("checkbox",()=>Click(check));Check(w.Editor.Rows[0].Enabled!=old,"Checkbox did not toggle");});
   await Test("Ctrl and Shift selections preserve workspace",async()=>{while(w.Editor.Rows.Count<4)w.Editor.Rows.Add(w.Editor.Rows[0].CloneDisabled());await Stable();outer.Offset=default;await Unmoved("multiple",()=>{Click(Cell(0));Click(Cell(2),KeyModifiers.Control);});Check(grid.SelectedItems.Count==2,"Ctrl selection failed");await Unmoved("range",()=>{Click(Cell(0));Click(Cell(2),KeyModifiers.Shift);});Check(grid.SelectedItems.Count==3,"Shift selection failed");});
   await Test("keyboard navigation scrolls inside list",async()=>{for(int i=0;i<60;i++)w.Editor.Rows.Add(w.Editor.Rows[0].CloneDisabled());await Stable();Click(Cell(0));for(int i=0;i<25;i++){var focus=w.FocusManager?.GetFocusedElement() as Control??grid;focus.RaiseEvent(new KeyEventArgs{RoutedEvent=InputElement.KeyDownEvent,Key=Key.Down});await Task.Delay(10);}await Stable();Check(grid.SelectedIndex>=20,"Down did not move selection");var bar=grid.GetVisualDescendants().OfType<ScrollBar>().First(s=>s.Orientation==global::Avalonia.Layout.Orientation.Vertical&&s.TemplatedParent==grid);events.Add(new{Keyboard=Snapshot(),bar.Value,bar.Maximum});Check(bar.Value>0,"Inner list did not scroll");void KeyPress(Key key,KeyModifiers modifiers=KeyModifiers.None)=>(w.FocusManager?.GetFocusedElement() as Control??grid).RaiseEvent(new KeyEventArgs{RoutedEvent=InputElement.KeyDownEvent,Key=key,KeyModifiers=modifiers});int index=grid.SelectedIndex;KeyPress(Key.Up);await Stable();Check(grid.SelectedIndex==index-1,"Up failed");index=grid.SelectedIndex;KeyPress(Key.PageDown);await Stable();Check(grid.SelectedIndex>index,"PageDown failed");KeyPress(Key.PageUp);await Stable();Check(grid.SelectedIndex<=index,"PageUp failed");KeyPress(Key.End,KeyModifiers.Control);await Stable();Check(grid.SelectedIndex==w.Editor.Rows.Count-1&&bar.Value>0,"Ctrl+End failed");KeyPress(Key.Home,KeyModifiers.Control);await Stable();Check(grid.SelectedIndex==0&&bar.Value<1,"Ctrl+Home failed");});
   await Test("stacked workspace bottom remains reachable",async()=>{w.Width=700;w.Height=500;await Stable();outer.Offset=new Vector(0,outer.Extent.Height);await Stable();Check(outer.Offset.Y>0&&Math.Abs(outer.Offset.Y-(outer.Extent.Height-outer.Viewport.Height))<1,"Bottom unreachable");Capture("stacked-bottom");});
   await Test("offscreen focus remains visible",async()=>{outer.Offset=default;await Stable();var clear=w.FindControl<Button>("ChooseCoverButton")!;clear.Focus(NavigationMethod.Tab);await Stable();double y=clear.TranslatePoint(default,outer)!.Value.Y;Check(clear.IsFocused&&y>=0&&y+clear.Bounds.Height<=outer.Viewport.Height+1,"Tab focus hidden outside workspace");Capture("tab-cover");});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{File.WriteAllText(Path.Combine(folder,"measurements.json"),JsonSerializer.Serialize(events,new JsonSerializerOptions{WriteIndented=true}));await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
